// Hermetic element-attachment E2E (element-pages 7.1): the FULL production
// element path in one process — attach → queue drain → namespace + provenance
// written; sibling untouched; re-scan keeps the attachment. It JOINS the two
// existing harness pieces over their real joints: the scan-shaped PutItem
// upsert semantics of TestElement_Parsers_AttachmentLifetime (element_parsers_
// test.go) with the real-queue drain of the enrich package's attachment tests —
// but here every joint is the production one: the REAL module registry, the
// REAL enrich Queue with its production resolver (deps.Plugins.MetadataSource,
// not a test seam), REAL go-plugin SUBPROCESSES (the shipped tv-parser for the
// chain + the hermetic element fixture for the attached parser — tmdb stays
// seeded-but-unloaded exactly as production), and the REAL store. No mocks.
package itest

import (
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/enrich"
	"github.com/mellifera/mellifera/internal/module"
	"github.com/mellifera/mellifera/internal/plugin"
	"github.com/mellifera/mellifera/internal/store"
	"github.com/mellifera/mellifera/pkg/sdk"
)

// TestElement_Parsers_HermeticE2E drives attach → drain → re-scan over the
// composed production graph (see the file comment for the joint inventory).
func TestElement_Parsers_HermeticE2E(t *testing.T) {
	ctx := context.Background()
	tmp := t.TempDir()
	st, err := store.Open(ctx, filepath.Join(tmp, "element-e2e.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}

	// The REAL metadata_source plugins: tv-parser (the tv chain's one loaded
	// source — the seeded tmdb slot stays unloaded, production B1 shape) and
	// the hermetic element fixture (the anitomy-class undeclared parser), both
	// launched as real subprocesses through the real Manager.
	tvBin := buildBinary(t, tmp, "element-e2e-tv-parser", "./plugins/tv-parser")
	elemBin := buildBinary(t, tmp, "element-e2e-element-parser", "./internal/itest/testdata/element-parser")
	mgr := plugin.Open(plugin.Deps{
		MagicCookieKey:   "MELLIFERA_MAGIC_COOKIE",
		MagicCookieValue: "mellifera-plugin-v1",
		CoreVersion:      "0.1.0",
	})
	metaCaps := []sdk.Capability{{Type: "metadata_source", ID: "default", ProtoService: "mellifera.metadata.v1.MetadataSource"}}
	for id, path := range map[string]string{"tv-parser": tvBin, "anitomy": elemBin} {
		if err := mgr.Load(id, path, metaCaps); err != nil {
			t.Fatalf("load %s: %v", id, err)
		}
		if err := mgr.Start(ctx, id); err != nil {
			t.Fatalf("start %s: %v", id, err)
		}
	}
	t.Cleanup(func() {
		stopCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = mgr.Stop(stopCtx, "tv-parser")
		_ = mgr.Stop(stopCtx, "anitomy")
	})

	libID, err := st.CreateLibrary(ctx, "tv", filepath.Join(tmp, "lib"), "TV")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	// scanPut mirrors the scan path (the element_parsers_test idiom): the item
	// id is the deterministic composite of (libraryID, file_id) — the upsert
	// lands on the same id when the file is re-observed — and a fresh scan
	// document carries parsed only (no namespaces yet). The relative path is
	// TV-shaped so the real tv-parser's Match applies (the SxxExx token).
	scanPut := func(t *testing.T, fileID, relPath string) string {
		t.Helper()
		id := fmt.Sprintf("itm_%d_%s", libID, fileID)
		doc, _ := json.Marshal(map[string]any{
			"file_id":        fileID,
			"module_type":    "tv",
			"schema_version": 1,
			"parsed":         map[string]any{"relative_path": relPath, "stem": "S01E01"},
		})
		if err := st.PutItem(ctx, store.Item{
			ID: id, ModuleID: "tv", LibraryID: libID, FileID: fileID,
			RelativePath: relPath, MediaType: "video",
			Document: doc, Status: "pending", SchemaVersion: 1,
		}); err != nil {
			t.Fatalf("PutItem %s: %v", id, err)
		}
		return id
	}

	attached := scanPut(t, "file-1", "Show/S01E01.mkv")
	sibling := scanPut(t, "file-2", "Show/S01E02.mkv")

	// ATTACH: the D-3 control-table write, via the store's API lane — the
	// queue is a reader of it.
	if err := st.SetItemParsers(ctx, attached, []string{"anitomy"}); err != nil {
		t.Fatalf("SetItemParsers: %v", err)
	}

	// DRAIN: the real queue, its resolver the production plugin.Manager — the
	// attachment derives (item, anitomy) work and the chain drains serially
	// ahead of it.
	q := enrich.NewQueue(enrich.Deps{Store: st, Modules: reg, Plugins: mgr}, enrich.QueueConfig{Backoff: time.Millisecond})
	if err := q.Start(ctx); err != nil {
		t.Fatalf("queue Start: %v", err)
	}
	t.Cleanup(q.Stop)
	q.Notify(ctx, libID)

	it := awaitItemReady(t, st, attached, 10*time.Second)
	var doc map[string]any
	if err := json.Unmarshal(it.Document, &doc); err != nil {
		t.Fatalf("decode attached document: %v", err)
	}
	// Namespace + provenance written (the standard trail): the core DIRECTED
	// the namespace id from the attachment (sources.anitomy), while the
	// payload is the fixture parser's own field; _provenance credits the
	// attachment id, _stages records an ok run — and the CHAIN drained through
	// the real tv-parser subprocess ahead of the extra.
	sources, _ := doc["sources"].(map[string]any)
	ns, ok := sources["anitomy"].(map[string]any)
	if !ok {
		t.Fatalf("sources.anitomy absent after drain: %v", sources)
	}
	if ns["title"] != "element-parser" {
		t.Fatalf("sources.anitomy = %v, want the fixture's namespace payload", ns)
	}
	if _, ok := sources["tv-parser"]; !ok {
		t.Fatalf("sources.tv-parser absent after drain (chain did not run): %v", sources)
	}
	prov, _ := doc["_provenance"].(map[string]any)
	p, _ := prov["title"].(map[string]any)
	if p == nil || p["plugin_id"] != "anitomy" {
		t.Fatalf("_provenance.title = %v, want an anitomy provenance entry", prov["title"])
	}
	foundStage := false
	stages, _ := doc["_stages"].([]any) // store round-trip: JSON array -> []any
	for _, raw := range stages {
		s, _ := raw.(map[string]any)
		if pid, _ := s["plugin_id"].(string); pid == "anitomy" && s["status"] == "ok" {
			foundStage = true
		}
	}
	if !foundStage {
		t.Fatalf("_stages has no ok entry for anitomy: %v", doc["_stages"])
	}

	// SIBLING UNTOUCHED: no attachment -> no anitomy namespace, while the
	// sibling's own chain still drains it to ready.
	sib := awaitItemReady(t, st, sibling, 10*time.Second)
	var sibDoc map[string]any
	if err := json.Unmarshal(sib.Document, &sibDoc); err != nil {
		t.Fatalf("decode sibling document: %v", err)
	}
	sibSources, _ := sibDoc["sources"].(map[string]any)
	if _, ok := sibSources["anitomy"]; ok {
		t.Fatalf("sibling gained sources.anitomy (attachment leaked): %v", sibSources)
	}

	// RE-SCAN (same root): the scanner re-observes the same file_id, so the
	// scan-shaped upsert lands on the SAME item identity — the attachment
	// must survive the re-scan untouched.
	attached = scanPut(t, "file-1", "Show/S01E01.mkv")
	got, err := st.ListItemParsers(ctx, attached)
	if err != nil {
		t.Fatalf("ListItemParsers after re-scan: %v", err)
	}
	if len(got) != 1 || got[0] != "anitomy" {
		t.Fatalf("after re-scan: attachments = %v, want [anitomy] (re-scan survival)", got)
	}
}

// awaitItemReady polls the store until the item settles to ready (all queueable
// sources terminal) or the deadline elapses.
func awaitItemReady(t *testing.T, st *store.Store, id string, timeout time.Duration) store.Item {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		it, err := st.GetItem(context.Background(), id)
		if err == nil && it.Status == "ready" {
			return it
		}
		time.Sleep(5 * time.Millisecond)
	}
	it, _ := st.GetItem(context.Background(), id)
	t.Fatalf("item %s status = %q, want ready (timeout %v)", id, it.Status, timeout)
	return it
}
